/** @brief A fixed op's payload length, or -1 when it carries a tail. */
static inline int
tiku_dl_op_fixed(uint16_t op)
{
    switch (op) {
    case 1u: return 12;
    case 2u: return 12;
    case 3u: return 16;
    case 4u: return 10;
    case 5u: return 10;
    case 8u: return 8;
    case 9u: return 0;
    case 16u: return 8;
    case 17u: return 8;
    case 18u: return 12;
    case 24u: return 16;
    case 25u: return 10;
    case 28u: return 14;
    case 29u: return 14;
    case 30u: return 6;
    default: return -1;
    }
}

/** @brief The least an op carrying text can be: its head and one
 *         terminator; -1 for an op that carries none. */
static inline int
tiku_dl_op_least(uint16_t op)
{
    switch (op) {
    case 6u: return 10;
    case 7u: return 14;
    case 19u: return 13;
    case 20u: return 13;
    case 21u: return 13;
    case 22u: return 13;
    case 26u: return 13;
    case 27u: return 13;
    case 31u: return 13;
    case 32u: return 13;
    default: return -1;
    }
}

/** @brief Where an op's text starts in its payload, or -1 for none. */
